    16  /** @file
    17   * @brief tests H3 vertex functions.
    18   */
    19
    20  #include "test.h"
    21  #include "utility.h"
    22  #include "vertex.h"
    23
    24  SUITE(Vertex) {
    25      TEST(vertexNumForDirection_hex) {
    26          H3Index origin = 0x823d6ffffffffff;
    27          int vertexNums[NUM_HEX_VERTS] = {0};
    28          for (Direction dir = K_AXES_DIGIT; dir < NUM_DIGITS; dir++) {
    29              int vertexNum = vertexNumForDirection(origin, dir);
    30              t_assert(vertexNum >= 0 && vertexNum < NUM_HEX_VERTS,
    31                       "vertex number appears valid");
    32              t_assert(!vertexNums[vertexNum], "vertex number appears only once");
    33              vertexNums[vertexNum] = 1;
    34          }
    35      }
    36
    37      TEST(vertexNumForDirection_pent) {
    38          H3Index pentagon = 0x823007fffffffff;
    39          int vertexNums[NUM_PENT_VERTS] = {0};
    40          for (Direction dir = J_AXES_DIGIT; dir < NUM_DIGITS; dir++) {
    41              int vertexNum = vertexNumForDirection(pentagon, dir);
    42              t_assert(vertexNum >= 0 && vertexNum < NUM_PENT_VERTS,
    43                       "vertex number appears valid");
    44              t_assert(!vertexNums[vertexNum], "vertex number appears only once");
    45              vertexNums[vertexNum] = 1;
    46          }
    47      }
    48
    49      TEST(vertexNumForDirection_badDirections) {
    50          H3Index origin = 0x823007fffffffff;
    51
    52          t_assert(
    53              vertexNumForDirection(origin, CENTER_DIGIT) == INVALID_VERTEX_NUM,
    54              "center digit should return invalid vertex");
    55          t_assert(
    56              vertexNumForDirection(origin, INVALID_DIGIT) == INVALID_VERTEX_NUM,
    57              "invalid digit should return invalid vertex");
    58
    59          H3Index pentagon = 0x823007fffffffff;
    60          t_assert(
    61              vertexNumForDirection(pentagon, K_AXES_DIGIT) == INVALID_VERTEX_NUM,
    62              "K direction on pentagon should return invalid vertex");
    63      }
    64
    65      TEST(directionForVertexNum_hex) {
    66          H3Index origin = 0x823d6ffffffffff;
    67          bool seenDirs[NUM_DIGITS] = {false};
    68          for (int vertexNum = 0; vertexNum < NUM_HEX_VERTS; vertexNum++) {
    69              Direction dir = directionForVertexNum(origin, vertexNum);
    70              t_assert(dir > 0 && dir < INVALID_DIGIT, "direction appears valid");
    71              t_assert(!seenDirs[dir], "direction appears only once");
    72              seenDirs[dir] = true;
    73          }
    74      }
    75
    76      TEST(directionForVertexNum_badVerts) {
    77          H3Index origin = 0x823d6ffffffffff;
    78
    79          t_assert(directionForVertexNum(origin, -1) == INVALID_DIGIT,
    80                   "negative vertex should return invalid direction");
    81          t_assert(directionForVertexNum(origin, 6) == INVALID_DIGIT,
    82                   "invalid vertex should return invalid direction");
    83
    84          H3Index pentagon = 0x823007fffffffff;
    85          t_assert(directionForVertexNum(pentagon, 5) == INVALID_DIGIT,
    86                   "invalid pent vertex should return invalid direction");
    87      }
    88
    89      TEST(cellToVertex_badVerts) {
    90          H3Index origin = 0x823d6ffffffffff;
    91
    92          H3Index vert;
    93          t_assert(H3_EXPORT(cellToVertex)(origin, -1, &vert) == E_DOMAIN,
    94                   "negative vertex should return null index");
    95          t_assert(H3_EXPORT(cellToVertex)(origin, 6, &vert) == E_DOMAIN,
    96                   "invalid vertex should return null index");
    97
    98          H3Index pentagon = 0x823007fffffffff;
    99          t_assert(H3_EXPORT(cellToVertex)(pentagon, 5, &vert) == E_DOMAIN,
   100                   "invalid pent vertex should return null index");
   101      }
   102
   103      TEST(cellToVertex_invalid) {
   104          H3Index invalid = 0xFFFFFFFFFFFFFFFF;
   105          H3Index vert;
   106          t_assert(H3_EXPORT(cellToVertex)(invalid, 3, &vert) == E_FAILED,
   107                   "Invalid cell returns error");
   108      }
   109
   110      TEST(isValidVertex_hex) {
   111          H3Index origin = 0x823d6ffffffffff;
   112          H3Index vert = 0x2222597fffffffff;
   113
   114          t_assert(H3_EXPORT(isValidVertex)(vert), "known vertex is valid");
   115
   116          for (int i = 0; i < NUM_HEX_VERTS; i++) {
   117              t_assertSuccess(H3_EXPORT(cellToVertex)(origin, i, &vert));
   118              t_assert(H3_EXPORT(isValidVertex)(vert), "vertex is valid");
   119          }
   120      }
   121
   122      TEST(isValidVertex_invalidOwner) {
   123          H3Index origin = 0x823d6ffffffffff;
   124          int vertexNum = 0;
   125          H3Index vert;
   126          t_assertSuccess(H3_EXPORT(cellToVertex)(origin, vertexNum, &vert));
   127
   128          // Set a bit for an unused digit to something else.
   129          vert ^= 1;
   130
   131          t_assert(H3_EXPORT(isValidVertex)(vert) == 0,
   132                   "vertex with invalid owner is not valid");
   133      }
   134
   135      TEST(isValidVertex_wrongOwner) {
   136          H3Index origin = 0x823d6ffffffffff;
   137          int vertexNum = 0;
   138          H3Index vert;
   139          t_assertSuccess(H3_EXPORT(cellToVertex)(origin, vertexNum, &vert));
   140
   141          // Assert that origin does not own the vertex
   142          H3Index owner = vert;
   143          H3_SET_MODE(owner, H3_CELL_MODE);
   144          H3_SET_RESERVED_BITS(owner, 0);
   145
   146          t_assert(origin != owner, "origin does not own the canonical vertex");
   147
   148          H3Index nonCanonicalVertex = origin;
   149          H3_SET_MODE(nonCanonicalVertex, H3_VERTEX_MODE);
   150          H3_SET_RESERVED_BITS(nonCanonicalVertex, vertexNum);
   151
   152          t_assert(H3_EXPORT(isValidVertex)(nonCanonicalVertex) == 0,
   153                   "vertex with incorrect owner is not valid");
   154      }
   155
   156      TEST(isValidVertex_badVerts) {
   157          H3Index origin = 0x823d6ffffffffff;
   158          t_assert(H3_EXPORT(isValidVertex)(origin) == 0, "cell is not valid");
   159
   160          H3Index fakeEdge = origin;
   161          H3_SET_MODE(fakeEdge, H3_DIRECTEDEDGE_MODE);
   162          t_assert(H3_EXPORT(isValidVertex)(fakeEdge) == 0,
   163                   "edge mode is not valid");
   164
   165          H3Index vert;
   166          t_assertSuccess(H3_EXPORT(cellToVertex)(origin, 0, &vert));
   167          H3_SET_RESERVED_BITS(vert, 6);
   168          t_assert(H3_EXPORT(isValidVertex)(vert) == 0,
   169                   "invalid vertexNum is not valid");
   170
   171          H3Index pentagon = 0x823007fffffffff;
   172          H3Index vert2;
   173          t_assertSuccess(H3_EXPORT(cellToVertex)(pentagon, 0, &vert2));
   174          H3_SET_RESERVED_BITS(vert2, 5);
   175          t_assert(H3_EXPORT(isValidVertex)(vert2) == 0,
   176                   "invalid pentagon vertexNum is not valid");
   177      }
   178
   179      TEST(vertexToLatLng_invalid) {
   180          H3Index invalid = 0xFFFFFFFFFFFFFFFF;
   181          LatLng latLng;
   182          t_assert(H3_EXPORT(vertexToLatLng)(invalid, &latLng) != E_SUCCESS,
   183                   "Invalid vertex returns error");
   184      }
   185
   186      TEST(cellToVertexes_invalid) {
   187          H3Index invalid = 0xFFFFFFFFFFFFFFFF;
   188          H3Index verts[6] = {0};
   189          t_assert(H3_EXPORT(cellToVertexes)(invalid, verts) == E_FAILED,
   190                   "cellToVertexes fails for invalid cell");
   191      }
   192  }
